# ===================== Auto-save all matplotlib figures =====================
# All figures generated by plt.show() will be saved here instead of popping up.
OUTPUT_DIR = Path(r"C:\Users\zt623\OneDrive - Imperial College London\Other documents\Project SWIFT\examineChanging1")
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
SAVE_FIGURES_AUTOMATICALLY = True
_fig_counter = 1


def _safe_filename(text: str, fallback: str = "figure") -> str:
    text = str(text).strip() or fallback
    text = re.sub(r"[^A-Za-z0-9\u4e00-\u9fff._ -]+", "_", text)
    text = re.sub(r"\s+", "_", text)
    return text[:160]


def _figure_title(fig) -> str:
    if getattr(fig, "_suptitle", None) is not None:
        title = fig._suptitle.get_text()
        if title:
            return title
    for ax in fig.axes:
        title = ax.get_title()
        if title:
            return title
    return "figure"


def save_current_figures(close: bool = True):
    """Save all currently open matplotlib figures to OUTPUT_DIR."""
    global _fig_counter
    saved_paths = []
    for num in plt.get_fignums():
        fig = plt.figure(num)
        title = _safe_filename(_figure_title(fig), fallback=f"figure_{_fig_counter:03d}")
        path = OUTPUT_DIR / f"{_fig_counter:03d}_{title}.png"
        fig.savefig(path, dpi=300, bbox_inches="tight")
        saved_paths.append(path)
        _fig_counter += 1
        if close:
            plt.close(fig)
    return saved_paths


def _save_instead_of_show(*args, **kwargs):
    """Replacement for plt.show(): save figures instead of displaying popup windows."""
    if not SAVE_FIGURES_AUTOMATICALLY:
        return
    saved = save_current_figures(close=True)
    for path in saved:
        print(f"Saved figure: {path}")


plt.show = _save_instead_of_show
