# Make the numbers readable
def format_base_value(var, value):
    if "price" in var or "cost" in var:
        return f"£{value:.2f}"
    elif "rate" in var:
        return f"{value*100:.1f}%"
    elif "km" in var:
        return f"{value:.0f} km"
    else:
        return f"{value}"
    
# TCO results   
def pretty_summary() -> str:
    shared = SharedInputs()
